'use strict';
let friendLobbyTab='match';
window.setFriendLobbyTab=tab=>{friendLobbyTab=tab;for(const id of ['match','list']){document.getElementById('friend-section-'+id).hidden=id!==tab;document.getElementById('friend-tab-'+id).setAttribute('aria-pressed',String(id===tab));}if(typeof receiveFriendInvitations==='function')receiveFriendInvitations(friendInvitations);};
let friendDirectory=null,friendListBusy=false,friendListTimer=null;
function friendListMessage(text){document.getElementById('friend-list-status').textContent=text;}
function renderFriendDirectory(){
 if(typeof invitationsFromDirectory==='function')invitationsFromDirectory();
 if(!friendDirectory)return;document.getElementById('friend-own-code').textContent=friendDirectory.code;const count=friendDirectory.entries.filter(e=>e.status==='accepted').length;document.getElementById('friend-limit-status').textContent='フレンド '+count+' / '+(friendDirectory.limit||50)+'人（申請中は含みません）';const box=document.getElementById('friend-list');box.replaceChildren();
 for(const status of ['incoming','accepted','outgoing']){
  const entries=friendDirectory.entries.filter(e=>e.status===status);if(!entries.length)continue;const title=document.createElement('h4');title.textContent={incoming:'届いた申請',accepted:'登録済みのフレンド',outgoing:'承認待ちの申請'}[status];box.append(title);
  for(const entry of entries){const row=document.createElement('article');row.className='friend-directory-row';row.dataset.friendCode=entry.code;const identity=document.createElement('div');identity.className='friend-player-row';const icon=document.createElement('span');icon.className='player-avatar';paintPlayerAvatar(icon,entry.profile);const name=document.createElement('div');paintPlayerName(name,entry.profile);const code=document.createElement('small');code.textContent=entry.code;name.append(code);identity.append(icon,name);const actions=document.createElement('div');actions.className='friend-row-actions';
   const button=(text,action,kind)=>{const b=document.createElement('button');b.type='button';b.className='inventory-action secondary';b.textContent=text;b.dataset.friendAction=kind;b.disabled=friendListBusy||friendBusy;b.onclick=action;actions.append(b);return b;};
   if(status==='incoming')button('承認',()=>changeFriend(entry.code,'accept'),'accept');
   if(status==='accepted'){if(entry.invitation){row.dataset.invited='true';const note=document.createElement('p');note.className='friend-invitation-label';note.textContent='対戦の招待が届いています';name.append(note);const b=button('対戦の招待に参加',()=>joinFriendInvitation(entry.invitation),'join');b.disabled=friendListBusy||friendBusy||!!friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching;}else{const b=button('対戦に招待',()=>createFriendRoom(entry.code),'invite');b.disabled=friendListBusy||friendBusy||!!friendRoom;}}
   if(status==='accepted'){const cpu=button('CPUと対戦',()=>startFriendCpuBattle(entry.code),'cpu');cpu.disabled=friendListBusy||friendBusy||!!friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching;}
   button(status==='incoming'?'断る':status==='outgoing'?'申請を取り消す':'登録を解除',()=>changeFriend(entry.code,'remove'),'remove');row.append(identity,actions);box.append(row);
  }
 }
 if(!friendDirectory.entries.length){const p=document.createElement('p');p.textContent='まだフレンドがいません。コードを交換して登録できます。';box.append(p);}
}
window.loadFriendList=async()=>{if(friendListBusy)return;try{if(!friendDirectory)await ensurePlayerProfile();friendDirectory=await playerApi('/api/friends');renderFriendDirectory();friendListMessage('');}catch(error){friendListMessage(error.message);}finally{scheduleFriendList();}};
function scheduleFriendList(){clearTimeout(friendListTimer);if(!document.hidden&&!document.getElementById('modal-friends').classList.contains('hidden'))friendListTimer=setTimeout(loadFriendList,5000);}
window.requestFriend=async()=>{if(friendListBusy)return;const code=document.getElementById('friend-add-code').value.trim().toUpperCase();if(!/^[A-Z2-9]{8}$/.test(code)){friendListMessage('8文字のフレンドコードを入力してください。');return;}friendListBusy=true;document.getElementById('btn-friend-request').disabled=true;friendListMessage('申請中…');try{await ensurePlayerProfile();friendDirectory=await playerApi('/api/friends/request','POST',{code});renderFriendDirectory();const e=friendDirectory.entries.find(e=>e.code===code);friendListMessage(e?.status==='accepted'?'登録済みのフレンドです。':e?.status==='incoming'?'相手から申請が届いています。「承認」を押してください。':'申請しました。相手の承認を待っています。');}catch(error){friendListMessage(error.message);}finally{friendListBusy=false;document.getElementById('btn-friend-request').disabled=false;renderFriendDirectory();scheduleFriendList();}};
window.changeFriend=async(code,action)=>{if(friendListBusy)return;friendListBusy=true;renderFriendDirectory();try{friendDirectory=await playerApi(`/api/friends/${code}/${action}`,'POST',{});friendListMessage(action==='accept'?'フレンドに登録しました。':'登録・申請を解除しました。');}catch(error){friendListMessage(error.message);}finally{friendListBusy=false;renderFriendDirectory();scheduleFriendList();}};
window.copyOwnFriendCode=async()=>{if(!friendDirectory)return;try{await navigator.clipboard.writeText(friendDirectory.code);friendListMessage('フレンドコードをコピーしました。');}catch{friendListMessage('コードを長押ししてコピーできます。');}};
window.joinFriendInvitation=async code=>{if(friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching){friendListMessage('参加中の対局・オンライン検索を終了してから参加できます。');return;}document.getElementById('friend-room-code').value=code;await joinFriendRoom();if(friendRoom?.code===code&&typeof receiveFriendInvitations==='function')receiveFriendInvitations(friendInvitations.filter(e=>e.code!==code));};
window.prepareFriendRematch=async()=>{if(friendBusy||!friendRoom||friendRoom.status!=='finished'||friendRoom.departed)return;setFriendBusy(true);setFriendStatus('次のバトルの準備中…');try{await loadFriendSetup();const team=friendRoster();await ensurePlayerProfile();acceptFriendRoom(await playerApi(`/api/friends/rooms/${friendRoom.code}/rematch`,'POST',{round:friendRoom.round,team}),false);startFriendPolling();}catch(error){setFriendStatus(error.message);}finally{setFriendBusy(false);}};
window.cancelFriendReady=async()=>{if(friendBusy||!friendRoom||!['preparing','finished'].includes(friendRoom.status))return;setFriendBusy(true);try{acceptFriendRoom(await playerApi(`/api/friends/rooms/${friendRoom.code}/${friendRoom.status==='preparing'?'ready':'rematch'}`,'POST',friendRoom.status==='preparing'?{revision:friendRoom.revision,lineupRevision:friendRoom.lineupRevision,round:friendRoom.round,ready:false}:{round:friendRoom.round,ready:false}),false);startFriendPolling();}catch(error){setFriendStatus(error.message);}finally{setFriendBusy(false);}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(friendListTimer);else if(!document.getElementById('modal-friends').classList.contains('hidden'))loadFriendList();});
